// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        Drain sink = new Drain();
        vm.deal(address(c), amount);
        c.forward(address(sink), "");
        assertTrue(address(c).balance == amount);
    }
}

contract Drain {
    fallback() external payable {
        payable(msg.sender).call{value: address(this).balance}("");
    }
}
